Examples.Python:
import boto3

s3 = boto3.client('s3')
kms = boto3.client('kms')

# SNAPSHOT
try:
    enc = s3.get_bucket_encryption(Bucket=bucket_name)['ServerSideEncryptionConfiguration']
    current_rule = enc['Rules'][0]
    current_algo = current_rule['ApplyServerSideEncryptionByDefault']['SSEAlgorithm']
    current_key = current_rule['ApplyServerSideEncryptionByDefault'].get('KMSMasterKeyID')
    current_bucket_key = current_rule.get('BucketKeyEnabled', False)
except s3.exceptions.ClientError as e:
    if 'ServerSideEncryptionConfigurationNotFoundError' in str(e):
        current_algo = None
        current_key = None
        current_bucket_key = False
    else:
        raise

# Verify KMS key if CMK specified
if kms_key_id and kms_key_id != 'aws/s3':
    key_meta = kms.describe_key(KeyId=kms_key_id)['KeyMetadata']
    if not key_meta['Enabled']:
        raise RuntimeError(f"KMS key {kms_key_id} is disabled")
    target_key_arn = key_meta['Arn']

# Pre-check
if current_algo == 'aws:kms' and (not kms_key_id or current_key == kms_key_id or (kms_key_id and current_key == target_key_arn)):
    print('Already compliant — SSE-KMS configured'); exit(0)

# FIX: Configure SSE-KMS
enc_default = {'SSEAlgorithm': 'aws:kms'}
if kms_key_id:
    enc_default['KMSMasterKeyID'] = kms_key_id

s3.put_bucket_encryption(
    Bucket=bucket_name,
    ServerSideEncryptionConfiguration={
        'Rules': [{
            'ApplyServerSideEncryptionByDefault': enc_default,
            'BucketKeyEnabled': bucket_key_enabled if bucket_key_enabled is not None else True
        }]
    }
)

# VERIFY
verify = s3.get_bucket_encryption(Bucket=bucket_name)['ServerSideEncryptionConfiguration']
verify_rule = verify['Rules'][0]
assert verify_rule['ApplyServerSideEncryptionByDefault']['SSEAlgorithm'] == 'aws:kms'
if kms_key_id and kms_key_id != 'aws/s3':
    assert verify_rule['ApplyServerSideEncryptionByDefault'].get('KMSMasterKeyID') == target_key_arn
assert verify_rule.get('BucketKeyEnabled', False) is True
print('SUCCESS: SSE-KMS configured with Bucket Keys enabled')

Examples.Terraform:
resource "aws_s3_bucket_server_side_encryption_configuration" "sse_kms" {
  bucket = var.bucket_name

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_key_id  # Use aws_kms_key.example.arn for CMK, or omit for aws/s3
    }
    bucket_key_enabled = true
  }
}

# If using a customer managed key, ensure it exists:
resource "aws_kms_key" "s3_encryption" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "s3_encryption" {
  name          = "alias/${var.bucket_name}-encryption"
  target_key_id = aws_kms_key.s3_encryption.key_id
}

# For existing buckets not managed by Terraform, import first:
# terraform import aws_s3_bucket_server_side_encryption_configuration.sse_kms my-bucket-name

